 #include <QAction>
 #include <QActionGroup>
@@ -146,6 +147,49 @@ QStringList Backend::applicationCategories(const QUrl &launcherUrl)
     return desktopFile.desktopGroup().readXdgListEntry(QStringLiteral("Categories"));
 }

+static KService::Ptr menuEditorService()
+{
+    return KService::serviceByDesktopName(QStringLiteral("org.kde.kmenuedit"));
+}
+
+// The application a launcher URL points at, if it has a menu entry the menu editor can open.
+static KService::Ptr editableApplication(const QUrl &launcherUrl)
+{
+    const QUrl desktopEntryUrl = Backend::tryDecodeApplicationsUrl(launcherUrl);
+
+    if (!desktopEntryUrl.isValid() || !desktopEntryUrl.isLocalFile() || !KDesktopFile::isDesktopFile(desktopEntryUrl.toLocalFile())) {
+        return {};
+    }
+
+    const KService::Ptr service = KService::serviceByDesktopPath(desktopEntryUrl.toLocalFile());
+
+    if (!service || !service->isApplication() || service->menuId().isEmpty()) {
+        return {};
+    }
+
+    return service;
+}
+
+bool Backend::canEditApplication(const QUrl &launcherUrl) const
+{
+    return editableApplication(launcherUrl) && menuEditorService();
+}
+
+void Backend::editApplication(const QUrl &launcherUrl) const
+{
+    const KService::Ptr service = editableApplication(launcherUrl);
+    const KService::Ptr menuEditor = menuEditorService();
+
+    if (!service || !menuEditor) {
+        return;
+    }
+
+    auto *job = new KIO::CommandLauncherJob(menuEditor->exec(), {service->menuId()});
+    job->setDesktopName(menuEditor->desktopEntryName());
+    job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoErrorHandlingEnabled));
+    job->start();
+}
+
 QVariantList Backend::jumpListActions(const QUrl &launcherUrl, QObject *parent)
 {
     QVariantList actions;
